
.help-page{min-height:100vh;display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-pack:center;-ms-flex-pack:center;justify-content:center;-webkit-box-align:safe center;-ms-flex-align:safe center;align-items:safe center;padding:28px 18px 56px;-webkit-box-sizing:border-box;box-sizing:border-box
}
.help-wrap{width:100%;max-width:360px;text-align:left;color:var(--ink)
}
.help-back{width:40px;cursor:pointer;margin-bottom:16px;color:var(--ink)
}
.help-wrap h1{font-size:40px;font-weight:700;line-height:1.1;margin:0 0 8px
}
.help-wrap h2{font-size:22px;font-weight:700;line-height:1.2;margin:28px 0 8px
}
.help-wrap p{font-size:18px;font-weight:400;line-height:1.45;margin:0 0 12px
}
.palette-row{display:-webkit-box;display:-ms-flexbox;display:flex;-ms-flex-wrap:wrap;flex-wrap:wrap;gap:20px 14px
}
.palette-choice{-webkit-box-flex:0;-ms-flex:0 0 calc(33.333% - 6px);flex:0 0 calc(33.333% - 6px);display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-orient:vertical;-webkit-box-direction:normal;-ms-flex-direction:column;flex-direction:column;-webkit-box-align:center;-ms-flex-align:center;align-items:center;gap:8px;margin:0;padding:0;border:none;background:rgba(0,0,0,0);color:var(--ink);font:inherit;cursor:pointer
}
.palette-plate{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;-webkit-box-pack:center;-ms-flex-pack:center;justify-content:center;width:100%;-webkit-box-sizing:border-box;box-sizing:border-box;min-height:86px;padding:14px 10px;border-radius:12px
}
.palette-tile{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-orient:vertical;-webkit-box-direction:normal;-ms-flex-direction:column;flex-direction:column;-webkit-box-align:center;-ms-flex-align:center;align-items:center;-webkit-box-pack:center;-ms-flex-pack:center;justify-content:center;gap:3px;width:58px;height:58px;-webkit-box-sizing:border-box;box-sizing:border-box;border:2px solid var(--line);border-radius:8px;-webkit-box-shadow:0 3px 0 var(--lip);box-shadow:0 3px 0 var(--lip)
}
.palette-choice.is-on .palette-plate{outline:3px solid var(--ink);outline-offset:3px
}
.palette-num{font-size:16px;font-weight:700;line-height:1
}
.palette-grid{display:grid;grid-template-columns:repeat(3, 7px);grid-template-rows:repeat(3, 7px);gap:1px
}
.palette-grid i{display:block;border-radius:1px
}
.palette-label{font-size:14px;font-weight:700;line-height:1
}
.shot{margin:0
}
.shot img{display:block;width:100%;background:var(--tile);border:2px solid var(--ink);border-radius:8px;-webkit-box-shadow:0 3px 0 var(--ink);box-shadow:0 3px 0 var(--ink)
}
.shot-missing{min-height:168px;-webkit-box-sizing:border-box;box-sizing:border-box;display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-orient:vertical;-webkit-box-direction:normal;-ms-flex-direction:column;flex-direction:column;-webkit-box-align:center;-ms-flex-align:center;align-items:center;-webkit-box-pack:center;-ms-flex-pack:center;justify-content:center;gap:8px;padding:20px;text-align:center;background:var(--tile);color:var(--ink);border:2px dashed var(--ink);border-radius:8px;font-size:16px
}
.shot-file{font-weight:700
}
.shot figcaption{margin-top:8px;font-size:16px;line-height:1.3
}


