
DIV.level-dots.level-dots{display:grid;grid-template-columns:repeat(3, 1fr);grid-template-rows:repeat(3, 1fr);gap:2px;-webkit-box-flex:0;-ms-flex:none;flex:none;align-self:center;width:34px;height:34px;min-height:0;margin:0;padding:0;border:none;-webkit-box-shadow:none;box-shadow:none;background:rgba(0,0,0,0);font-size:0;line-height:0
}
.level-dots SPAN{display:block;width:auto;height:auto;min-width:0;min-height:0;margin:0;padding:0;border:none;border-radius:2px;-webkit-box-shadow:none;box-shadow:none;font-size:0;line-height:0
}
.dot-orange{background:var(--mark-off)
}
.dot-green{background:var(--mark-on)
}
.passed .dot-green{background:var(--passed-dot-on)
}
.passed .dot-orange{background:var(--passed-dot-off)
}


