
.problem-row{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:start;-ms-flex-align:start;align-items:flex-start;-webkit-box-pack:center;-ms-flex-pack:center;justify-content:center;gap:20px;margin-top:12px
}
.problem-row .math{margin-left:0;margin-right:0
}
.problem-tools{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-orient:vertical;-webkit-box-direction:normal;-ms-flex-direction:column;flex-direction:column;-webkit-box-align:center;-ms-flex-align:center;align-items:center;gap:14px;width:48px;padding-top:16px
}
#toggleh{position:relative;width:40px;height:80px;margin:0
}
.toggle-rot{position:absolute;width:80px;height:40px;left:50%;top:50%;-webkit-transform:translate(-50%, -50%) rotate(90deg);transform:translate(-50%, -50%) rotate(90deg)
}
.smath{max-width:400px;margin-left:auto;margin-right:auto;height:160px;margin-bottom:8px;padding-top:30px
}
.math{font-size:4em;font-family:inherit;font-weight:700;font-variant-numeric:tabular-nums;color:var(--ink);background-color:var(--tile);border:2px solid var(--line);-webkit-box-shadow:0 3px 0 var(--lip);box-shadow:0 3px 0 var(--lip);max-width:300px;width:3em;margin-left:auto;margin-right:auto;border-radius:8px;margin-bottom:8px;padding:14px 30px 0 0;line-height:.95em;height:3.5em;overflow:hidden
}
.math DIV{text-align:right;margin-left:30px
}
.total{border-top:6px solid var(--ink);padding-top:5px;margin-top:12px
}
DIV.dtable{display:inline-block;height:122px;width:122px
}
.math.error{color:var(--miss);border-color:var(--miss);-webkit-box-shadow:0 3px 0 var(--miss);box-shadow:0 3px 0 var(--miss)
}
.math.error .total{border-top-color:var(--miss)
}
.square-holder{border:1px solid rgba(0,0,0,0)
}
.question-button{width:44px;background:var(--ink);color:var(--tile);font-family:inherit;font-size:28px;height:44px;line-height:44px;font-weight:700;cursor:pointer;border-radius:8px;-webkit-box-shadow:0 3px 0 var(--lip);box-shadow:0 3px 0 var(--lip);margin:0;position:static;-webkit-user-select:none;-moz-user-select:none;-ms-user-select:none;user-select:none
}
.question-button:active{-webkit-transform:translateY(2px);transform:translateY(2px);-webkit-box-shadow:0 1px 0 var(--lip);box-shadow:0 1px 0 var(--lip)
}


