
.fa-icon{width:auto;height:1em
}
.eq-button{line-height:.8
}
.eq{font-size:1.2em;font-weight:bold;line-height:.5em
}
.numpad{font-size:4em;font-weight:bold;display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-orient:horizontal;-webkit-box-direction:normal;-ms-flex-direction:row;flex-direction:row;-ms-flex-flow:row wrap;flex-flow:row wrap;width:4.2em;margin-left:auto;margin-right:auto;border:0px solid #ccc;border-radius:6px
}
.numpad DIV{width:1em;border:2px solid var(--line);border-radius:8px;background-color:var(--tile);color:var(--ink);-webkit-box-shadow:0 3px 0 var(--lip);box-shadow:0 3px 0 var(--lip);margin:2px;padding:8px;line-height:1;height:.9em;cursor:pointer;font-weight:700;-webkit-user-select:none;-moz-user-select:none;-ms-user-select:none;user-select:none
}
.numpad DIV:active{-webkit-transform:translateY(2px);transform:translateY(2px);-webkit-box-shadow:0 1px 0 var(--lip);box-shadow:0 1px 0 var(--lip)
}
.numpad DIV DIV{border:none;-webkit-box-shadow:none;box-shadow:none;background-color:rgba(0,0,0,0);width:auto;height:auto;margin:0;padding:0;line-height:0
}
.numpad DIV DIV:active{-webkit-transform:none;transform:none
}
.numpad .del{color:var(--miss);font-size:40px;line-height:1.8;height:57px;width:64px;display:block
}
.numpad .back{display:-webkit-box;display:-ms-flexbox;display:flex;-webkit-box-align:center;-ms-flex-align:center;align-items:center;-webkit-box-pack:center;-ms-flex-pack:center;justify-content:center;width:64px;height:57px;color:var(--ink);font-size:40px;line-height:1
}


